<!DOCTYPE html>
<html>
<head>
  <title>Sorting Algorithm Visualizer</title>
  <style>
    body {
      background-color: #1e1e1e;
      color: #d4d4d4;
      font-family: monospace;
      margin: 0;
      padding: 0;
    }

    #container {
      width: 80%;
      margin: 20px auto;
      background-color: #333;
      border: 1px solid #555;
      overflow: hidden;
      height: 400px; /* Added height for consistent display */
    }

    .bar {
      width: 20px;
      height: 0;
      background-color: steelblue;
      display: block;
      margin: 5px;
      box-sizing: border-box; /* Important to include padding and border in the width */
    }

    #controls {
      width: 80%;
      margin: 20px auto;
      background-color: #222;
      padding: 10px;
      border: 1px solid #444;
    }

    button {
      background-color: #444;
      color: #fff;
      padding: 5px 10px;
      border: none;
      cursor: pointer;
      margin-right: 10px;
    }

    button:hover {
      background-color: #555;
    }
  </style>
</head>
<body>
  <div id="container">
    <div class="bar" id="bar1"></div>
    <div class="bar" id="bar2"></div>
    <div class="bar" id="bar3"></div>
    <div class="bar" id="bar4"></div>
    <div class="bar" id="bar5"></div>
    <div class="bar" id="bar6"></div>
    <div class="bar" id="bar7"></div>
    <div class="bar" id="bar8"></div>
  </div>

  <div id="controls">
    <button id="sort">Sort</button>
    <button id="shuffle">Shuffle</button>
    <button id="reset">Reset</button>
  </div>

  <script>
    const array = [5, 2, 9, 1, 5, 6];
    const bars = document.querySelectorAll('.bar');
    let sorted = false;

    function updateBars() {
      for (let i = 0; i < array.length; i++) {
        bars[i].style.height = `${array[i]}px`;
      }
    }

    function sortStep() {
      if (sorted) return true;

      // Bubble Sort Implementation for demonstration
      for (let i = 0; i < array.length - 1; i++) {
        for (let j = 0; j < array.length - 1 - i; j++) {
          const bar1 = bars[j];
          const bar2 = bars[j + 1];

          if (array[j] > array[j + 1]) {
            // Swap elements
            const temp = array[j];
            array[j] = array[j + 1];
            array[j + 1] = temp;

            // Update bar heights
            const height1 = parseFloat(bar1.style.height);
            const height2 = parseFloat(bar2.style.height);
            bar1.style.height = `${height2}px`;
            bar2.style.height = `${height1}px`;

          }
        }
      }

      sorted = true;
      return sorted;
    }


    window.viz = {
      array: function() { return array.slice(); },
      setArray: function(a) {
        array.length = 0;
        for (let i = 0; i < a.length; i++) {
          array.push(a[i]);
        }
        updateBars();
      },
      sortStep: sortStep,
      sorted: function() { return sorted; }
    };

    window.addEventListener('DOMContentLoaded', () => {
      updateBars();

      const sortButton = document.getElementById('sort');
      const shuffleButton = document.getElementById('shuffle');
      const resetButton = document.getElementById('reset');

      sortButton.addEventListener('click', () => {
        sorted = false;
        sortStep();
      });

      shuffleButton.addEventListener('click', () => {
        const shuffledArray = [...array].sort(() => Math.random() - 0.5); // Shuffle the array
        window.viz.setArray(shuffledArray);
      });

      resetButton.addEventListener('click', () => {
        window.viz.setArray([5, 2, 9, 1, 5, 6]);
      });
    });
  </script>
</body>
</html>
